import { EventResult } from '@/types/event.types';
import { Roles } from '@/types/api.types';
import { Policies, isInPolicy } from '@/utils/roles';

/**
 * Mirrors the API's EventOperations.Manage policy (EventAccessPolicy.cs): the event's own
 * `owners` list, plus Admin_SuperAdmin. Event ownership is data on the event rather than a
 * role, so it cannot be expressed as a route role requirement.
 */
export const isEventOwner = (
    event: EventResult | null,
    userId: string,
    userRoles: Roles[],
): boolean => {
    if (isInPolicy(Policies.Admin_SuperAdmin, userRoles)) return true;
    if (!event || !userId) return false;
    return (event.owners ?? []).includes(userId);
};
